<?php
require __DIR__.'/../cms/config.php'; require_login();
$u=current_user(); if(in_array($u['role'],['admin','teacher'],true)){redirect('../cms/school.php');}
$students=read_json('students');$results=read_json('results');$attendance=read_json('attendance');$subjects=read_json('subjects');$ledger=read_json('ledger');$messages=read_json('messages');$parents=read_json('parents');$classes=read_json('classes');
$studentIds=[];
if($u['role']==='student' && !empty($u['profile_id'])) $studentIds=[(int)$u['profile_id']];
if($u['role']==='parent' && !empty($u['profile_id'])) foreach($students as $s)if((int)($s['parent_id']??0)===(int)$u['profile_id'])$studentIds[]=(int)$s['id'];
$myStudents=array_values(array_filter($students,fn($s)=>in_array((int)$s['id'],$studentIds,true)));
function sname($arr,$id){foreach($arr as $x)if((int)$x['id']===(int)$id)return $x['name']??'';return '—';}
function percent($m,$o){return $o?round(($m/$o)*100,1):0;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Ridgefield Portal</title><link rel="stylesheet" href="../cms/cms.css"><link rel="stylesheet" href="../assets/phase53-complete.css"><style>.portal-wrap{max-width:1200px;margin:auto;padding:30px}.hero-mini{background:#17312a;color:#fff;border-radius:18px;padding:32px;margin-bottom:22px}.portal-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:20px}.portal-card{background:#fff;border:1px solid #dde3dd;border-radius:14px;padding:22px}.portal-table{width:100%;border-collapse:collapse}.portal-table th,.portal-table td{padding:10px;border-bottom:1px solid #e2e6e2;text-align:left}.metric{font-size:34px;font-weight:700}.top{display:flex;justify-content:space-between;gap:15px;align-items:center;margin-bottom:20px}.badge{display:inline-block;background:#edf2ed;border-radius:30px;padding:5px 10px;font-size:12px}@media(max-width:800px){.portal-grid{grid-template-columns:1fr}.portal-wrap{padding:18px}.portal-table{display:block;overflow:auto}}</style><link rel="stylesheet" href="../assets/dynamic-site.css">
<link rel="stylesheet" href="../assets/phase35.css">
</head><body class="rf-dynamic"><div class="portal-wrap"><div class="top"><a href="../index.html" style="display:inline-flex;align-items:center"><img src="../assets/2026.png" alt="Ridgefield Academy" style="display:block;width:auto;height:52px;max-width:220px;object-fit:contain"></a><div><?=h($u['name'])?> · <a href="change-password.php">Change password</a> · <a href="messages.php">Messages</a> · <a href="timetable.php">Timetable</a> · <a href="logout.php">Sign out</a></div></div><section class="hero-mini"><p class="eyebrow">PRIVATE PORTAL</p><h1>Welcome, <?=h($u['name'])?></h1><p>Your academic and school information is shown only to your authorised account.</p></section>
<?php if(!$myStudents):?><div class="alert error">Your portal account has not yet been linked to a student record. Please contact the school administration.</div><?php endif;?>
<?php foreach($myStudents as $st):?>
<div class="portal-card" style="margin-bottom:20px"><div class="top"><div><h2><?=h($st['name'])?></h2><span class="badge"><?=h($st['student_no'])?> · Grade <?=h($st['grade'])?></span></div><div><strong><?=h(sname($classes,(int)($st['class_id']??0)))?></strong><br><a href="profile.php?student_id=<?=h((string)$st['id'])?>">Full profile</a> · <a href="report.php?student_id=<?=h((string)$st['id'])?>">Report card</a></div></div>
<div class="portal-grid">
<section class="portal-card"><h3>Academic progress</h3><table class="portal-table"><tr><th>Subject</th><th>Assessment</th><th>Term</th><th>Result</th></tr><?php $rows=array_values(array_filter($results,fn($r)=>(int)$r['student_id']===(int)$st['id']));foreach(array_reverse($rows) as $r):?><tr><td><?=h(sname($subjects,(int)$r['subject_id']))?></td><td><?=h($r['assessment'])?></td><td><?=h($r['term'])?></td><td><strong><?=h((string)$r['mark'])?>/<?=h((string)$r['out_of'])?></strong><br><small><?=percent($r['mark'],$r['out_of'])?>%</small></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="4">No results have been published yet.</td></tr><?php endif;?></table></section>
<section class="portal-card"><h3>Attendance</h3><?php $ar=array_values(array_filter($attendance,fn($a)=>(int)$a['student_id']===(int)$st['id']));$present=count(array_filter($ar,fn($a)=>in_array($a['status'],['Present','Late'],true)));?><div class="metric"><?=count($ar)?round($present/count($ar)*100,1):'—'?><?php if($ar):?>%<?php endif;?></div><p>Attendance rate</p><table class="portal-table"><tr><th>Date</th><th>Status</th></tr><?php foreach(array_slice(array_reverse($ar),0,10) as $a):?><tr><td><?=h($a['date'])?></td><td><?=h($a['status'])?></td></tr><?php endforeach;?></table></section>
<section class="portal-card"><h3>Account</h3><?php $lr=array_values(array_filter($ledger,fn($l)=>(int)$l['student_id']===(int)$st['id']));$balance=0;foreach($lr as $l)$balance+=($l['type']==='Payment'||$l['type']==='Credit')?-(float)$l['amount']:(float)$l['amount'];?><div class="metric">R <?=number_format($balance,2)?></div><p>Current ledger balance</p><table class="portal-table"><tr><th>Date</th><th>Description</th><th>Amount</th></tr><?php foreach(array_slice(array_reverse($lr),0,8) as $l):?><tr><td><?=h($l['date'])?></td><td><?=h($l['description'])?></td><td>R <?=number_format((float)$l['amount'],2)?></td></tr><?php endforeach;?></table></section>
<section class="portal-card"><h3>Messages</h3><?php $mr=array_values(array_filter($messages,fn($m)=>(int)$m['recipient_id']===(int)$u['id']));foreach(array_reverse($mr) as $m):?><article style="border-bottom:1px solid #e2e6e2;padding:10px 0"><strong><?=h($m['subject'])?></strong><p><?=nl2br(h($m['body']))?></p><small><?=h($m['created_at'])?></small></article><?php endforeach;if(!$mr):?><p>No messages.</p><?php endif;?></section>
</div></div><?php endforeach;?>
</div><script src="assets/dynamic-site.js"></script>
